## `modules/rds/main.tf`

```hcl
resource "aws_db_subnet_group" "main" {
  name            = "${var.identifier}-subnet-group"
  subnet_ids      = var.db_subnet_ids
  tags = {
    Environment = var.environment
  }
}

resource "aws_security_group" "rds" {
  name        = "${var.identifier}-sg"
  description = "Security group for RDS ${var.identifier}"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.app_security_group_ids
    description     = "PostgreSQL from app security group"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = {
    Environment = var.environment
  }
}

resource "aws_db_instance" "main" {
  identifier              = var.identifier
  allocated_storage       = var.allocated_storage
  storage_type            = "gp3"
  engine                  = "postgres"
  engine_version          = var.postgres_version
  instance_class          = var.instance_class
  db_name                 = var.db_name
  username                = var.master_username
  password                = var.master_password
  parameter_group_name    = aws_db_parameter_group.main.name
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  publicly_accessible     = false
  skip_final_snapshot     = var.environment == "dev" ? true : false
  final_snapshot_identifier = var.environment == "dev" ? null : "${var.identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  storage_encrypted           = true
  kms_key_id                  = var.kms_key_id
  multi_az                    = var.multi_az
  backup_retention_period     = var.backup_retention_days
  backup_window               = "03:00-04:00"
  maintenance_window          = "sun:04:00-sun:05:00"
  copy_tags_to_snapshot       = true
  deletion_protection         = var.deletion_protection
  enabled_cloudwatch_logs_exports = ["postgresql"]
  enable_iam_database_authentication = true

  tags = {
    Environment = var.environment
  }

  depends_on = [aws_db_subnet_group.main]
}

resource "aws_db_parameter_group" "main" {
  family = "postgres${split(".", var.postgres_version)[0]}"
  name   = "${var.identifier}-params"

  tags = {
    Environment = var.environment
  }

  # Production-ready parameters
  parameter {
    name  = "log_statement"
    value = "all"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }
}
```

## `modules/rds/variables.tf`

```hcl
variable "identifier" {
  description = "RDS instance identifier"
  type        = string

  validation {
    condition     = can(regex("^[a-z0-9-]{1,63}$", var.identifier))
    error_message = "Identifier must be 1-63 chars, lowercase alphanumeric and hyphens."
  }
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "allocated_storage" {
  description = "Allocated storage in GiB"
  type        = number

  validation {
    condition     = var.allocated_storage >= 20 && var.allocated_storage <= 65536
    error_message = "Allocated storage must be between 20 and 65536 GiB."
  }
}

variable "instance_class" {
  description = "RDS instance class (e.g., 'db.t3.micro', 'db.t3.medium')"
  type        = string

  validation {
    condition     = can(regex("^db\\.", var.instance_class))
    error_message = "Instance class must start with 'db.'."
  }
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  sensitive   = true

  validation {
    condition     = can(regex("^[a-z_][a-z0-9_]*$", var.master_username))
    error_message = "Username must start with a letter or underscore."
  }
}

variable "master_password" {
  description = "Master password (use AWS Secrets Manager or environment variable)"
  type        = string
  sensitive   = true

  validation {
    condition     = length(var.master_password) >= 8
    error_message = "Password must be at least 8 characters."
  }
}

variable "postgres_version" {
  description = "PostgreSQL version"
  type        = string
  default     = "15.4"
}

variable "backup_retention_days" {
  description = "Backup retention period in days"
  type        = number
  default     = 7

  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
  default     = false
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "KMS key ID for encryption"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID"
  type        = string
}

variable "db_subnet_ids" {
  description = "List of subnet IDs for RDS subnet group"
  type        = list(string)

  validation {
    condition     = length(var.db_subnet_ids) >= 2
    error_message = "At least 2 subnets required for RDS subnet group."
  }
}

variable "app_security_group_ids" {
  description = "Security group IDs of application servers"
  type        = list(string)
}
```

