## `modules/iam/main.tf`

```hcl
resource "aws_iam_role" "service_account" {
  name               = var.role_name
  assume_role_policy = var.environment == "prod" ? data.aws_iam_policy_document.trust_policy_prod[0].json : data.aws_iam_policy_document.trust_policy_dev[0].json

  tags = {
    Environment = var.environment
  }
}

# Dev: Basic role trust (for EC2, ECS, or inline tests)
data "aws_iam_policy_document" "trust_policy_dev" {
  count = var.environment == "dev" ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com", "ecs-tasks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# Prod: OIDC trust (for EKS/IRSA)
data "aws_iam_policy_document" "trust_policy_prod" {
  count = var.environment == "prod" ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    actions = ["sts:AssumeRoleWithWebIdentity"]
    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub"
      values   = ["system:serviceaccount:${var.oidc_namespace}:${var.oidc_service_account}"]
    }
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${var.role_name}-policy"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.permissions.json
}

# Least-privilege policy: no wildcards in prod
data "aws_iam_policy_document" "permissions" {
  # S3 permissions
  statement {
    sid    = "S3Access"
    effect = "Allow"
    actions = var.environment == "prod" ? [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ] : [
      "s3:*"
    ]
    resources = var.environment == "prod" ? [
      var.s3_bucket_arn,
      "${var.s3_bucket_arn}/*"
    ] : [
      "*"
    ]
  }

  # RDS permissions
  statement {
    sid    = "RDSAccess"
    effect = "Allow"
    actions = var.environment == "prod" ? [
      "rds-db:connect"
    ] : [
      "rds:DescribeDBInstances",
      "rds:DescribeDBClusters"
    ]
    resources = var.environment == "prod" ? [
      var.rds_instance_arn
    ] : [
      "*"
    ]
  }

  # Secrets Manager (for DB connection string) - only in prod
  dynamic "statement" {
    for_each = var.environment == "prod" ? [1] : []
    content {
      sid    = "SecretsManagerAccess"
      effect = "Allow"
      actions = [
        "secretsmanager:GetSecretValue"
      ]
      resources = [
        "arn:aws:secretsmanager:*:*:secret:${var.role_name}-*"
      ]
    }
  }
}

# Inline user creation for dev (programmatic access)
resource "aws_iam_user" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${var.role_name}-user"

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_user_policy" "service_account" {
  count  = var.environment == "dev" ? 1 : 0
  name   = "${var.role_name}-user-policy"
  user   = aws_iam_user.service_account[0].name
  policy = data.aws_iam_policy_document.permissions.json
}

resource "aws_iam_access_key" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}
```

## `modules/iam/variables.tf`

```hcl
variable "role_name" {
  description = "Name of the IAM role/user"
  type        = string

  validation {
    condition     = can(regex("^[a-zA-Z0-9+=,.@_-]{1,64}$", var.role_name))
    error_message = "Role name must be 1-64 characters with valid characters."
  }
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "s3_bucket_arn" {
  description = "ARN of the S3 bucket to grant access to"
  type        = string
}

variable "rds_instance_arn" {
  description = "ARN of the RDS instance to grant access to"
  type        = string
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC provider (for prod/EKS)"
  type        = string
  default     = null
}

variable "oidc_namespace" {
  description = "Kubernetes namespace for IRSA (prod only)"
  type        = string
  default     = "default"
}

variable "oidc_service_account" {
  description = "Kubernetes service account name (prod only)"
  type        = string
  default     = "default"
}
```

## `modules/iam/outputs.tf`

```hcl
output "role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.service_account.arn
}

output "role_name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.service_account.name
}

output "user_arn" {
  description = "ARN of the IAM user (dev only)"
  value       = try(aws_iam_user.service_account[0].arn, null)
}

output "access_key_id" {
  description = "Access key ID for IAM user (dev only, sensitive)"
  value       = try(aws_iam_access_key.service_account[0].id, null)
  sensitive   = true
}

output "secret_access_key" {
  description = "Secret access key for IAM user (dev only, sensitive)"
  value       = try(aws_iam_access_key.service_account[0].secret, null)
  sensitive   = true
}
```

