## Root Module: `main.tf`

```hcl
module "s3" {
  source = "./modules/s3"

  bucket_name                      = var.s3_bucket_name
  environment                      = var.environment
  kms_key_id                       = var.use_kms ? aws_kms_key.main[0].id : null
  enable_cross_region_replication  = var.environment == "prod"
  replication_target_region        = "us-west-2"
}

module "rds" {
  source = "./modules/rds"

  identifier              = var.rds_identifier
  environment             = var.environment
  allocated_storage       = var.rds_allocated_storage
  instance_class          = var.rds_instance_class
  db_name                 = var.db_name
  master_username         = var.rds_master_username
  master_password         = var.rds_master_password
  postgres_version        = var.postgres_version
  backup_retention_days   = var.backup_retention_days
  multi_az                = var.environment == "prod"
  deletion_protection     = true
  kms_key_id              = var.use_kms ? aws_kms_key.main[0].id : null
  vpc_id                  = var.vpc_id
  db_subnet_ids           = var.db_subnet_ids
  app_security_group_ids  = var.app_security_group_ids
}

module "iam" {
  source = "./modules/iam"

  role_name          = var.iam_role_name
  environment        = var.environment
  s3_bucket_arn      = module.s3.bucket_arn
  rds_instance_arn   = module.rds.arn
  oidc_provider_arn  = var.environment == "prod" ? var.oidc_provider_arn : null
  oidc_namespace     = var.oidc_namespace
  oidc_service_account = var.oidc_service_account
}

# Optional: KMS key for encryption
resource "aws_kms_key" "main" {
  count                   = var.use_kms ? 1 : 0
  description             = "KMS key for ${var.environment} environment"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Environment = var.environment
  }
}

resource "aws_kms_alias" "main" {
  count         = var.use_kms ? 1 : 0
  name          = "alias/${var.environment}-app-key"
  target_key_id = aws_kms_key.main[0].key_id
}
```

