## Environment Files

### `environments/dev.tfvars`

```hcl
environment              = "dev"
aws_region              = "us-east-1"
s3_bucket_name          = "app-assets-dev-${data.aws_caller_identity.current.account_id}"
use_kms                 = false
rds_identifier          = "app-db-dev"
rds_allocated_storage   = 20
rds_instance_class      = "db.t3.micro"
db_name                 = "appdb_dev"
rds_master_username     = "postgres"
# rds_master_password set via environment variable: TF_VAR_rds_master_password
postgres_version        = "15.4"
backup_retention_days   = 7
vpc_id                  = "vpc-xxxxx"
db_subnet_ids           = ["subnet-xxxxx", "subnet-yyyyy"]
app_security_group_ids  = ["sg-xxxxx"]
iam_role_name           = "app-service-account-dev"
oidc_namespace          = "default"
oidc_service_account    = "app-service"
```

### `environments/prod.tfvars`

```hcl
environment              = "prod"
aws_region              = "us-east-1"
s3_bucket_name          = "app-assets-prod-${data.aws_caller_identity.current.account_id}"
use_kms                 = true
rds_identifier          = "app-db-prod"
rds_allocated_storage   = 100
rds_instance_class      = "db.t3.medium"
db_name                 = "appdb_prod"
rds_master_username     = "postgres"
# rds_master_password set via environment variable or Secrets Manager
postgres_version        = "15.4"
backup_retention_days   = 30
vpc_id                  = "vpc-yyyyy"
db_subnet_ids           = ["subnet-aaaaa", "subnet-bbbbb"]
app_security_group_ids  = ["sg-yyyyy"]
iam_role_name           = "app-service-account-prod"
oidc_provider_arn       = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLID"
oidc_namespace          = "production"
oidc_service_account    = "app-service"
```

